//! SipHash-2-4 (standard) and the Warp 10 "palindromic" variant.
//!
//! Ported line-by-line from `io.warp10.crypto.SipHashInline`
//! (senx/warp10-platform, `crypto` module). Validated against the upstream
//! JUnit vectors (`SipHashInlineTest`) and fresh golden vectors generated by
//! compiling the upstream Java class — see `tests/vectors.rs`.

#[inline(always)]
fn sipround(v: &mut [u64; 4]) {
    // Same operations as siphash24.c, in the hand-reordered (dependency
    // friendly) order used by SipHashInline.
    v[0] = v[0].wrapping_add(v[1]);
    v[2] = v[2].wrapping_add(v[3]);
    v[1] = v[1].rotate_left(13);
    v[3] = v[3].rotate_left(16);
    v[1] ^= v[0];
    v[3] ^= v[2];
    v[0] = v[0].rotate_left(32);
    v[2] = v[2].wrapping_add(v[1]);
    v[0] = v[0].wrapping_add(v[3]);
    v[1] = v[1].rotate_left(17);
    v[3] = v[3].rotate_left(21);
    v[1] ^= v[2];
    v[3] ^= v[0];
    v[2] = v[2].rotate_left(32);
}

#[inline(always)]
fn msround(v: &mut [u64; 4], m: u64) {
    v[3] ^= m;
    sipround(v);
    sipround(v);
    v[0] ^= m;
}

#[inline(always)]
fn init_v(k0: u64, k1: u64) -> [u64; 4] {
    [
        0x736f6d6570736575 ^ k0,
        0x646f72616e646f6d ^ k1,
        0x6c7967656e657261 ^ k0,
        0x7465646279746573 ^ k1,
    ]
}

#[inline(always)]
fn finalize(mut v: [u64; 4]) -> u64 {
    v[2] ^= 0xff;
    sipround(&mut v);
    sipround(&mut v);
    sipround(&mut v);
    sipround(&mut v);
    v[0] ^ v[1] ^ v[2] ^ v[3]
}

#[inline(always)]
fn le64(b: &[u8]) -> u64 {
    u64::from_le_bytes(b[..8].try_into().unwrap())
}

/// Split a 16-byte key into (k0, k1), big-endian, as `SipHashInline.getKey`
/// (the key bytes are read BE; message blocks are read LE).
pub fn get_key(key: &[u8]) -> [u64; 2] {
    assert!(key.len() >= 16);
    [
        u64::from_be_bytes(key[..8].try_into().unwrap()),
        u64::from_be_bytes(key[8..16].try_into().unwrap()),
    ]
}

/// Standard SipHash-2-4 (`hash24`), little-endian blocks + length byte.
pub fn hash24(k0: u64, k1: u64, data: &[u8]) -> u64 {
    let mut v = init_v(k0, k1);
    let len = data.len();
    let len8 = len - len % 8;
    let mut idx = 0;
    while idx < len8 {
        let m = le64(&data[idx..idx + 8]);
        idx += 8;
        msround(&mut v, m);
    }
    let mut m = (len as u64) << 56;
    for k in 0..len - len8 {
        m |= (data[len8 + k] as u64) << (8 * k);
    }
    msround(&mut v, m);
    finalize(v)
}

/// Warp 10 "palindromic" SipHash-2-4 (`hash24_palindromic`).
///
/// The message is conceptually doubled: D = data ++ reverse(data). Complete
/// 8-byte blocks of D are processed in order; a final block carries the
/// remaining bytes and the doubled length (2*len) in the top byte.
/// Ported exactly from the Java implementation (including its final-block
/// byte selection), so ids match the platform bit-for-bit.
pub fn hash24_palindromic(k0: u64, k1: u64, data: &[u8]) -> u64 {
    let mut v = init_v(k0, k1);
    let len = data.len();
    let last = (2 * len) / 8 * 8;
    let mut idx = 0usize;
    let len8 = len - len % 8;

    if last > 0 {
        // Full blocks fully contained in the forward part.
        while idx < len8 {
            let m = le64(&data[idx..idx + 8]);
            idx += 8;
            msround(&mut v, m);
        }
        // Middle block: spans the end of data; positions >= len wrap to
        // len-1-(pos%len), i.e. the reversed tail of the message.
        let mut m = 0u64;
        for k in 0..8 {
            let pos = idx + k;
            let p = if pos < len { pos } else { len - 1 - (pos % len) };
            m |= (data[p] as u64) << (8 * k);
        }
        idx += 8;
        msround(&mut v, m);
        // Remaining blocks of the doubled message, read backward.
        let offset2 = 2 * len - 1;
        while idx < last {
            let base = offset2 - (idx + 7);
            let m = le64(&data[base..base + 8]).swap_bytes();
            idx += 8;
            msround(&mut v, m);
        }
    }

    // Final block: length (2*len) in the top byte.
    let mut m = 0u64;
    if idx != 0 {
        let mut i = 0usize;
        while i < (2 * len - idx) {
            m = (m << 8) | data[i] as u64;
            i += 1;
        }
    } else {
        for i in 0..2 * len {
            let p = if i < len { i } else { len - 1 - (i % len) };
            m = (m << 8) | data[p] as u64;
        }
    }
    m |= (2 * len as u64) << 56;
    msround(&mut v, m);
    finalize(v)
}
